        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "금연교육이나 홍보를 외부 단체에 맡길 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장은 금연환경조성을 위한 금연교육 및 홍보관을 설치·운영하거나 금연환경조성 등 건강증진사업을 행하는 법인 또는 단체에 예산의 범위 안에서 교육 및 홍보에 관한 사항을 위탁할 수 있다.",
          "b_ids": "금연:제9조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
